    public function getSourceContext()
    {
        return new Source("{% extends 'base.html.twig' %}
{% block stylesheets %}
    {{ parent() }}
    {{ encore_entry_link_tags('logincss') }}

{% endblock %}
{% block title %}Connexion - {{ parent() }}{% endblock %}

{% block body %}
    <div class =\"row m-5\">
        <div class=\"col d-none d-lg-block\">
            <img src=\"{{asset('/build/images/evenement.png')}}\" class=\"img-fluid rounded\" alt=\"Responsive image\">
        </div>
        <div class=\"col-12 col-lg-6 d-flex justify-content-center\">
            <form method=\"post\" class=\" d-flex flex-column justify-content-center mx-auto\" id=\"formConnexion\">
                {% if error %}
                    <div class=\"alert alert-danger\">{{ error.messageKey|trans(error.messageData, 'security') }}</div>
                {% endif %}

                {% if app.user %}
                    <div class=\"mb-3\">
                        Vous etes connecté(e) en tant que {{ app.user.username }}, <a href=\"{{ path('app_logout') }}\">Déconnexion</a>
                    </div>
                {% endif %}

                <h1 class=\"h3 mb-3 font-weight-normal\">Connexion</h1>
                <label for=\"inputUsername\">Nom d'utilisateur</label>
                <input type=\"text\" value=\"{{ last_username }}\" name=\"username\" id=\"inputUsername\" class=\"form-control\" autocomplete=\"username\" required autofocus>
                <label for=\"inputPassword\">Mot de passe</label>
                <input type=\"password\" name=\"password\" id=\"inputPassword\" class=\"form-control\" autocomplete=\"current-password\" required>
                <input type=\"hidden\" name=\"_csrf_token\" value=\"{{ csrf_token('authenticate') }}\">
                {#
                    remember me functionality.
                    See https://symfony.com/doc/current/security/remember_me.html
                #}
                <a href=\"{{ path('app_forgot_password_request')}}\"> Mot de passe oublié ?</a>
                <div class=\"checkbox mb-3\">
                    <label>
                        <input type=\"checkbox\" name=\"_remember_me\" checked/>
                        Se souvenir de moi
                    </label>
                </div>
                <button class=\"btn btn-lg btn-primary mx-auto\" type=\"submit\">
                    Connexion
                </button>
            </form>
        </div>
    </div>
{% endblock %}
", "security/login.html.twig", "/home/lastrolalx/memoireastrolabe/templates/security/login.html.twig");
    }
